// Атрибут `inert` для React 18 (process-map-9ji).
//
// ЗАЧЕМ. Пока открыта боковая панель узла, полотно, крошки и легенда должны
// выпадать и из обхода Tab, и из режима чтения скринридера. Ровно это делает
// `inert`; `aria-hidden` для этого не годится — он прячет содержимое от
// ассистивной техники, но оставляет внутри фокусируемые кнопки, что само по
// себе нарушение ARIA.
//
// ПОЧЕМУ ФАЙЛ ВООБЩЕ НУЖЕН. React 18.3.1 не знает `inert` как проп, и
// @types/react 18.3.31 его не объявляет (проверено grep'ом по index.d.ts).
// В DOM атрибут при этом попадает нормально, если значение — СТРОКА: React 18
// пропускает неизвестные атрибуты со строковым значением, а на `inert={true}`
// ругается «Received `true` for a non-boolean attribute». Отсюда тип `''`, а
// не boolean: `undefined` убирает атрибут, пустая строка ставит.
//
// Аугментация HTMLAttributes покрывает и <ReactFlow>: его ReactFlowProps
// наследует Omit<HTMLAttributes<HTMLDivElement>, 'onError'>, а неизвестные
// пропы спредятся на обёртку полотна.
//
// КОГДА УДАЛИТЬ. В React 19 `inert` — штатный проп (уже boolean), и вместе с
// апгрейдом этот файл нужно снести, а вызовы перевести на `inert={drawerOpen}`.
import 'react';

declare module 'react' {
  // Параметр T не используется, но обязан быть и обязан называться так же:
  // слияние объявлений одного generic-интерфейса требует идентичного списка
  // параметров, включая имена.
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  interface HTMLAttributes<T> {
    inert?: '' | undefined;
  }
}
